declare module "*.py?raw" {
  const source: string;
  export default source;
}

declare module "*.txt?raw" {
  const source: string;
  export default source;
}

declare module "*LICENSE?raw" {
  const source: string;
  export default source;
}

declare module "*.ttf?inline" {
  const source: string;
  export default source;
}
